import type { Metadata } from "next";

type StartupImage = { url: string; media: string };

// [pixel width, pixel height, CSS width, CSS height, device pixel ratio]
// Files are generated by scripts/icons/generate.mjs into public/splash/.
const SIZES: ReadonlyArray<readonly [number, number, number, number, number]> = [
  [1320, 2868, 440, 956, 3],
  [1206, 2622, 402, 874, 3],
  [1290, 2796, 430, 932, 3],
  [1179, 2556, 393, 852, 3],
  [1284, 2778, 428, 926, 3],
  [1170, 2532, 390, 844, 3],
  [1125, 2436, 375, 812, 3],
  [828, 1792, 414, 896, 2],
  [750, 1334, 375, 667, 2],
];

/** Next Metadata `appleWebApp.startupImage` entries (portrait iPhone splash screens). */
export const appleStartupImages: StartupImage[] = SIZES.map(([w, h, cw, ch, dpr]) => ({
  url: `/splash/splash-${w}x${h}.png`,
  media: `(device-width: ${cw}px) and (device-height: ${ch}px) and (-webkit-device-pixel-ratio: ${dpr}) and (orientation: portrait)`,
}));

/** Exact public paths iOS fetches before sign-in; add these to the allowlist in src/server/auth/access.ts. */
export const splashPublicPaths: string[] = appleStartupImages.map((i) => i.url);

export const appleWebAppMetadata: NonNullable<Metadata["appleWebApp"]> = {
  capable: true,
  title: "Our Home",
  statusBarStyle: "black-translucent",
  startupImage: appleStartupImages,
};
